import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

// Loom ships no language servers and no hand-written server definitions. The
// catalog is generated by the language server publication workflow; it is the only
// file staged, and it may list no servers.
export function stageLspServers({
  catalog = fileURLToPath(new URL('../../../assets/lsp-servers/lsp-servers.toml', import.meta.url)),
  destination,
}) {
  if (!destination) throw new Error('Supply a destination for the language server catalog');
  if (!fs.existsSync(catalog)) throw new Error('Missing language server catalog: ' + catalog);
  fs.mkdirSync(destination, { recursive: true });
  const target = path.join(destination, 'lsp-servers.toml');
  fs.copyFileSync(catalog, target);
  return target;
}
